// Khanwa thumbnails (1280×720), in the channel's preferred style: painted hero art (generated by Codex, labelled a
// reconstruction), dark stormy side for the words, a framed gold place-and-year plate, two huge ivory-gold serif lines.
import React from "react";
import { AbsoluteFill, Img, staticFile, delayRender, continueRender } from "remotion";
import { loadFont } from "@remotion/fonts";

const h = delayRender("cinzel");
loadFont({ family: "Cinzel", url: staticFile("fonts/Cinzel-var.ttf"), weight: "400 900" }).then(() => continueRender(h));

type V = { art: string; lines: string[]; plate: string; flip?: boolean; pos?: string };
const VARIANTS: V[] = [
  { art: "thumb-art-charge.png", lines: ["THE RANA'S", "CHARGE"], plate: "KHANWA 1527" },
  { art: "thumb-art-babur.png", lines: ["THE CHAINED", "LINE"], plate: "KHANWA 1527" },
  { art: "thumb-art-charge.png", lines: ["CARTS", "vs", "CAVALRY"], plate: "KHANWA 1527" },
];

const Gold: React.FC<{ text: string; size: number; small?: boolean }> = ({ text, size, small }) => (
  <div style={{ position: "relative", fontFamily: "Cinzel", fontWeight: small ? 700 : 900, fontSize: size, lineHeight: 0.95, letterSpacing: small ? 2 : -1, whiteSpace: "nowrap" }}>
    {/* shadow and dark edge */}
    <div style={{ position: "absolute", inset: 0, color: "transparent", WebkitTextStroke: `${small ? 6 : 12}px rgba(10,8,6,0.85)`, filter: "drop-shadow(0 8px 14px rgba(0,0,0,0.9))" }}>{text}</div>
    {/* ivory-to-gold fill with a worn, mottled surface */}
    <div style={{ position: "relative", backgroundImage: small ? "linear-gradient(180deg, #f6c75a, #e08a2c)" : "linear-gradient(180deg, #fff6df 0%, #f3e3b4 45%, #d7b064 80%, #a97d32 100%)", WebkitBackgroundClip: "text", backgroundClip: "text", color: "transparent" }}>{text}</div>
    <div style={{ position: "absolute", inset: 0, color: "transparent", backgroundImage: "radial-gradient(rgba(60,40,15,0.28) 1px, transparent 1.6px), radial-gradient(rgba(60,40,15,0.18) 1.5px, transparent 2.2px)", backgroundSize: "7px 9px, 13px 11px", backgroundPosition: "0 0, 3px 5px", WebkitBackgroundClip: "text", backgroundClip: "text", mixBlendMode: "multiply" }}>{text}</div>
  </div>
);

export const KThumb: React.FC<{ v: number }> = ({ v }) => {
  const s = VARIANTS[v];
  return (
    <AbsoluteFill style={{ backgroundColor: "#000" }}>
      <Img src={staticFile(s.art)} style={{ position: "absolute", width: 1280, height: 720, objectFit: "cover", filter: "contrast(1.08) saturate(1.1)" }} />
      <AbsoluteFill style={{ background: "linear-gradient(90deg, rgba(6,12,30,0.85) 0%, rgba(6,12,30,0.55) 32%, rgba(6,12,30,0) 52%)" }} />
      <AbsoluteFill style={{ background: "radial-gradient(ellipse at 60% 50%, rgba(0,0,0,0) 55%, rgba(0,0,0,0.5) 100%)" }} />
      <div style={{ position: "absolute", left: 46, top: 52 }}>
        <div style={{ display: "inline-block", padding: "10px 26px 8px", background: "linear-gradient(180deg, #f2d47e, #c9a24a 55%, #a07a2c)", border: "3px solid #6b4b16", boxShadow: "0 0 0 2px #f2d47e inset, 0 6px 18px rgba(0,0,0,0.7)", fontFamily: "Cinzel", fontWeight: 800, fontSize: 46, letterSpacing: 4, color: "#1b1206" }}>{s.plate}</div>
        <div style={{ marginTop: 26 }}>
          {s.lines.map((l) => <Gold key={l} text={l} size={l === "vs" ? 70 : l.length > 8 ? 112 : 150} small={l === "vs"} />)}
        </div>
      </div>
    </AbsoluteFill>
  );
};
